function permanentIcon(e) { return wowIcon({ azIconKey: 'effect:' + e.id, name: e.name, icon: e.icon }); }
function permanentTrainingLis(cls, level) {
  if (!B.permanentEffects) return '';
  return B.permanentEffects(cls, null, true).map(function (e) { const on = level >= e.level;
    return '<li class="az-training-skill' + (on ? '' : ' az-ability-locked') + '" data-permanent-effect="' + esc(e.id) + '" data-available="' + on + '"><span class="az-training-icon" aria-hidden="true">' + permanentIcon(e) + '</span><div class="az-training-copy"><b class="az-training-name">' + esc(e.name) + '</b><strong class="az-training-state">' + esc(on ? 'Действует · с ' + e.level + ' уровня' : 'Откроется на ' + e.level + ' уровне') + '</strong><p class="az-training-description">' + esc(e.desc) + '</p><p class="az-training-meta">пассивно · само в начале каждого боя</p></div></li>'; }).join('');
}
function permanentSpecLis(cls, spec, level) {
  if (!B.permanentEffects) return '';
  return B.permanentEffects(cls, spec, false).map(function (e) { const on = level >= e.level;
    return '<li class="au" data-permanent-effect="' + esc(e.id) + '"' + (on ? '' : ' style="opacity:.55;filter:grayscale(1)"') + '><span class="sic" aria-hidden="true">' + permanentIcon(e) + '</span><span><b>' + esc(e.name) + '</b> <span class="scd">' + (on ? 'пассивно, весь бой' : 'с ' + e.level + ' ур.') + '</span><br>' + esc(e.desc) + '</span></li>'; }).join('');
}
